/* @lc app=leetcode id=2699 lang=kotlin */ class Solution { fun dij(n: Int, adj: Array<ArrayList<Int>>, eu: IntArray, ev: IntArray, s: Int, wf: (Int, Int, Long) -> Long): LongArray = LongArray(n) { Long.MAX_VALUE / 4 }.also { it[s] = 0 }.let { d -> java.util.PriorityQueue<Pair<Long, Int>>(compareBy<Pair<Long, Int>> { it.first }).also { it.add(0L to s) }.let { pq -> generateSequence { pq.poll() }.filter { (c, u) -> c == d[u] }.forEach { (c, u) -> adj[u].forEach { e -> (eu[e] xor ev[e] xor u).let { v -> (c + wf(e, u, c)).let { nc -> if (nc < d[v]) pq.add(nc to v).also { d[v] = nc } } } } }.let { d } } } fun modifiedGraphEdges(n: Int, edges: Array<IntArray>, source: Int, destination: Int, target: Int): Array<IntArray> = edges.size.let { m -> Array(n) { ArrayList<Int>() }.also { adj -> edges.forEachIndexed { i, e -> adj[e[0]].add(i).also { adj[e[1]].add(i) } } }.let { adj -> IntArray(m) { edges[it][0] }.let { eu -> IntArray(m) { edges[it][1] }.let { ev -> dij(n, adj, eu, ev, source) { e, _, _ -> if (edges[e][2] == -1) 1L else edges[e][2].toLong() }.let { d0 -> (target - d0[destination]).let { delta -> if (delta < 0) arrayOf<IntArray>() else LongArray(m).let { cur -> dij(n, adj, eu, ev, source) { e, u, du -> if (edges[e][2] != -1) edges[e][2].toLong() else if (cur[e] > 0) cur[e] else maxOf(1L, delta + d0[eu[e] xor ev[e] xor u] - du).also { cur[e] = it } }.let { d1 -> if (d1[destination] != target.toLong()) arrayOf<IntArray>() else Array(m) { intArrayOf(edges[it][0], edges[it][1], if (edges[it][2] != -1) edges[it][2] else if (cur[it] > 0) cur[it].toInt() else 1) } } } } } } } } } }